/* teste do desafio o-ordenador — counter_protocol (03-tdd 3.9.3).
   Fase VALOR: nada de captura de stdout. A funcao do aluno ordena a
   lista NO PROPRIO LUGAR, e cada cenario confere as gavetas depois da
   chamada. As tres listas sao diferentes: nenhuma sequencia fixa de
   valores passa nas tres. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void oOrdenador(int v[], int n);

SM_TEST(cinco_notas_fora_de_ordem) {
    int v[5] = {7, 3, 9, 1, 5};
    oOrdenador(v, 5);
    checa_int("a menor nota na gaveta 0", v[0], 1,
              "ordem crescente comeca pela menor nota da lista");
    checa_int("a segunda menor na gaveta 1", v[1], 3,
              "depois da menor vem a segunda menor");
    checa_int("a do meio na gaveta 2", v[2], 5,
              "o 5 fica no meio da lista ordenada");
    checa_int("a quarta na gaveta 3", v[3], 7,
              "o 7 e a segunda maior nota");
    checa_int("a maior nota na gaveta 4", v[4], 9,
              "a maior nota termina na ultima gaveta");
}

SM_TEST(a_lista_ja_ordenada_nao_desarruma) {
    int v[4] = {2, 4, 6, 8};
    oOrdenador(v, 4);
    checa_int("a gaveta 0 continua 2", v[0], 2,
