}

SM_TEST(a_lista_ao_contrario) {
    int v[4] = {9, 7, 5, 3};
    oOrdenador(v, 4);
    checa_int("a menor nota chegou a gaveta 0", v[0], 3,
              "a lista ao contrario e o pior caso: toda passada troca");
    checa_int("o 5 na gaveta 1", v[1], 5,
              "cada passada empurra um valor para o lugar dele");
    checa_int("o 7 na gaveta 2", v[2], 7,
              "cada passada empurra um valor para o lugar dele");
    checa_int("a maior nota chegou a gaveta 3", v[3], 9,
              "a primeira passada leva o 9 para o fim");
}

