#include <stdio.h>

void oOrdenador(int v[], int n) {
    for (int passada = 0; passada < n - 1; passada++) {
        for (int j = 0; j < n - 1 - passada; j++) {
            if (v[j + 1] < v[j]) {
                int guardado = v[j];
                v[j] = v[j + 1];
                v[j + 1] = guardado;
            }
        }
    }
}
